<template>
  <view class="detail-container">
    <!-- 顶部导航栏 -->
    <view class="header">
      <view class="back" @click="goBack">
        <image class="back-icon" src="@/static/icon/arrow-left-bold.svg" />
      </view>
      <view class="edit" @click="goEdit">
        <image class="edit-icon" src="@/static/icon/edit.svg" />
      </view>
    </view>

    <!-- 主体内容 -->
    <view class="content">
      <!-- 图片上传区域（当前仅展示占位图） -->
      <CameraUpload
        class="camera-upload"
        width="240rpx"
        height="240rpx"
        backgroundColor="rgba(217, 217, 217, 0.48)"
        borderRadius="12px"
      />

      <!-- 状态与分类标签 -->
      <view class="status-category">
        <view class="status">
          <text>{{ assetData?.status || '未知' }}</text>
        </view>
        <view class="category">
          <text>{{ assetData?.category || '未知' }}</text>
        </view>
      </view>

      <!-- 资产详情信息 -->
      <view class="asset-info">
        <view class="info-list">
          <!-- 资产名称 -->
          <view class="asset-name">
            <text class="value">{{ assetData?.name || '未知资产' }}</text>
          </view>

          <!-- 购入价格 -->
          <view class="info-item">
            <text class="label">购入价格</text>
            <text class="value">¥{{ assetData?.price || '0' }}</text>
          </view>

          <!-- 购买日期 -->
          <view class="info-item">
            <text class="label">购买日期</text>
            <text class="value">{{ assetData?.purchaseDate || '未填写' }}</text>
          </view>

          <!-- 保修日期 -->
          <view class="info-item">
            <text class="label">保修日期</text>
            <text class="value">{{ assetData?.warrantyDate || '—' }}</text>
          </view>

          <!-- 附加费用 -->
          <view class="info-item">
            <text class="label">附加费用</text>
            <text class="value">¥{{ assetData?.extraFee || '0' }}</text>
          </view>
        </view>
      </view>

    </view>

    <!-- 购买原因 -->
    <view class="buy-reason-container">
      <text class="content">{{ assetData?.buyReason || '未填写' }}</text>
    </view>

    <!-- 删除按钮 -->
    <view class="delete-button" @click="goDelete">
      <text>删除</text>
    </view>

    <!-- 编辑弹窗 -->
    <uni-popup ref="editPopup" type="bottom" @change="onPopupChange">
      <view class="popup-content">
        <!-- 弹窗头部 -->
        <view class="popup-header">
          <view class="popup-close" @click="closeEditPopup">
            <image class="popup-close-icon" src="@/static/icon/cancel.svg" />
          </view>
          <text class="popup-title">编辑资产</text>
          <view class="submit-btn" @click="submitEditForm">
            <image class="popup-submit-icon" src="@/static/icon/check.svg" />
          </view>
        </view>

        <!-- 表单组件：复用新增表单 -->
        <view class="popup-body">
          <AssetAddForm
            :asset-data="assetData"
            @submit="handleEditSubmit"
            ref="assetForm"
          />
        </view>
      </view>
    </uni-popup>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import CameraUpload from '@/components/common/CameraUpload.vue';
import AssetAddForm from '@/components/asset/AssetAddForm.vue';
import { fetchAssetDetail, updateAsset, deleteAsset } from '@/api/asset';

// 响应式数据
const assetData = ref(null);
const id = ref(0);
const editPopup = ref(null);
const assetForm = ref(null);

// 页面初始化：获取路由参数并加载详情
onMounted(() => {
  const pages = getCurrentPages();
  const currentPage = pages[pages.length - 1];
  const query = currentPage.options;
  id.value = parseInt(query.id, 10);

  if (id.value) {
    loadAssetDetail(id.value);
  } else {
    uni.showToast({ title: '无效资产ID', icon: 'none' });
    goBack();
  }
});

// 工具函数：格式化价格为两位小数字符串
const formatPrice = (price) => {
  if (price == null) return '0.00';
  return parseFloat(price).toFixed(2);
};

// 加载资产详情
const loadAssetDetail = async (assetId) => {
  try {
    const res = await fetchAssetDetail(assetId);
    assetData.value = {
      id: res.data.id,
      name: res.data.name,
      price: formatPrice(res.data.price),
      purchaseDate: res.data.purchaseDate,
      warrantyDate: res.data.warrantyDate || '',
      category: res.data.category,
      status: res.data.status,
      extraFee: formatPrice(res.data.additionalCost || '0'),
      buyReason: res.data.description || ''
    };
  } catch (error) {
    console.error('加载资产详情失败:', error);
    uni.showToast({ title: '加载失败', icon: 'none' });
    goBack();
  }
};

// 返回上一页或跳转到列表页
const goBack = () => {
  const pages = getCurrentPages();
  if (pages.length > 1) {
    uni.navigateBack();
  } else {
    uni.redirectTo({ url: '/pages/asset/list/list' });
  }
};

// 打开编辑弹窗
const goEdit = () => {
  editPopup.value.open();
};

// 关闭编辑弹窗
const closeEditPopup = () => {
  editPopup.value.close();
};

// 触发表单提交（调用子组件方法）
const submitEditForm = () => {
  assetForm.value?.submitForm();
};

// 处理编辑表单提交
const handleEditSubmit = async (formData) => {
  const payload = {
    name: formData.name,
    price: formData.price,
    purchaseDate: formData.buyDate,
    warrantyDate: formData.warrantyDate || null,
    status: formData.status,
    category: formData.category,
    additionalCost: formData.extraFee ? parseFloat(formData.extraFee).toFixed(2) : '0.00',
    description: formData.buyReason || ''
  };

  try {
    const res = await updateAsset(id.value, payload);
    assetData.value = {
      ...assetData.value,
      name: res.data.name ?? assetData.value.name,
      price: formatPrice(res.data.price ?? assetData.value.price),
      purchaseDate: res.data.purchaseDate ?? assetData.value.purchaseDate,
      warrantyDate: res.data.warrantyDate ?? assetData.value.warrantyDate,
      category: res.data.category ?? assetData.value.category,
      status: res.data.status ?? assetData.value.status,
      extraFee: formatPrice(res.data.additionalCost ?? assetData.value.extraFee),
      buyReason: res.data.description ?? assetData.value.buyReason
    };

    uni.showToast({ title: '修改成功', icon: 'success' });
    closeEditPopup();
  } catch (error) {
    console.error('修改失败:', error);
    uni.showToast({ title: '修改失败，请重试', icon: 'none' });
  }
};

// 删除资产（确认删除）
const goDelete = () => {
  uni.showModal({
    title: '确认删除',
    content: '确定要删除该资产吗？此操作不可恢复。',
    confirmText: '删除',
    confirmColor: '#FF4949',
    cancelText: '取消',
    success: async (res) => {
      if (res.confirm) {
        try {
          await deleteAsset(id.value);
          uni.showToast({ title: '删除成功', icon: 'success' });
          goBack();
        } catch (error) {
          console.error('删除失败:', error);
          uni.showToast({ title: '删除失败，请重试', icon: 'none' });
        }
      }
    }
  });
};

// 监听弹窗状态变化（预留扩展）
const onPopupChange = (e) => {
  // e.show === false 表示弹窗已关闭
};
</script>

